"use client";

import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { ClaimItemForm } from "./forms/claim-item-form";
import { useState } from "react";
import { ScrollArea } from "./ui/scroll-area";

type ClaimItemDialogProps = {
    itemId: string;
}

export function ClaimItemDialog({ itemId }: ClaimItemDialogProps) {
  const [open, setOpen] = useState(false);

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button size="lg" className="w-full text-lg">
          Claim Item
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-[425px] max-h-[90vh] flex flex-col">
        <DialogHeader>
          <DialogTitle>Submit a Claim</DialogTitle>
          <DialogDescription>
            To verify your ownership, please provide at least three unique identifying marks and optional proof of ownership.
          </DialogDescription>
        </DialogHeader>
        <ScrollArea className="flex-grow pr-6 -mr-6">
            <ClaimItemForm itemId={itemId} onSuccess={() => setOpen(false)} />
        </ScrollArea>
      </DialogContent>
    </Dialog>
  );
}
